mapper.select:
SELECT id, code, oauth_scope, resource, action, status, description, create_time, update_time
FROM sys_permission
WHERE code = #{code}

SELECT DISTINCT p.id, p.code, p.oauth_scope, p.resource, p.action, p.status, p.description, p.create_time, p.update_time FROM sys_permission p INNER JOIN sys_role_perm rp ON rp.perm_id = p.id WHERE p.status = 'active' AND rp.role_id IN
#{roleId}
ORDER BY p.code ASC, p.id ASC
